INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (372443, 15937, 'Navbharat Times', 'hi', 'UPSC : बदल सकता है 16 नंबर का गणित , CAT ने आयोग को भेजा नोटिस , मेन्स से ठीक पहले प्रीलिम्स पर उठे सवाल', 'https://navbharattimes.indiatimes.com/education/exam-results/before-upsc-cse-mains-2026-questions-raised-on-8-prelims-questions-cat-issues-notice-to-seeking-commission-response/articleshow/133315156.cms', '', 'https://static.langimg.com/nbt/thumb/123846288/navbharat-times.jpg?imgsize=123846288&resizemode=75', '20260818', '2026-08-18T09:21:52.407150'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (372649, 15937, 'Aaj Tak', 'hi', 'UPSC प्रील‍िम्स के 8 ''डिफेक्ट‍िव'' सवालों पर घिरा आयोग!', 'https://www.aajtak.in/education/news/story/upsc-civil-services-prelims-2026-question-dispute-cat-notice-edmm-dskc-2624816-2026-08-18', 'संघ लोक सेवा आयोग (UPSC) की सिविल सेवा प्रारंभिक परीक्षा 2026 विवादों में घिर गई है. GS Paper-1 के 8 ''गलत और त्रुटिपूर्ण'' सवालों को चुनौती देते हुए अभ्यर्थियों ने याचिका दायर की है. याचिका पर सुनवाई करते हुए सेंट्रल एडमिनिस्ट्रेटिव ट्रिब्यूनल (CAT) ने UPSC को नोटिस जारी कर जवाब मांगा है. छात्रों का दावा है कि इन 8 विवादित सवालों और नेगेटिव मार्किंग से 16 से अधिक नंबरों का फेरबदल हो रहा है, जिससे कई योग्य अभ्यर्थी मेन्स की रेस से बाहर हो गए हैं.', '', '2026-08-18T09:21:16+00:00', '2026-08-18T10:04:55.893877'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
